    total_competitors_needing_water = num_alive_opponents + 1

    if num_slots < total_competitors_needing_water:
        if my_status['hp'] <= 6:
            bid_to_make = max(bid_to_make, DAILY_SALARY * 0.95)
        elif my_status['hp'] > 6 and remaining_days <= 5:
            bid_to_make = max(bid_to_make, DAILY_SALARY * 0.75)
    elif num_slots >= total_competitors_needing_water and num_alive_opponents > 0:
        # Water is abundant, can bid lower to save budget
        bid_to_make = min(bid_to_make, DAILY_SALARY * 0.45)
        if yesterday_bids:
            bid_to_make = min(bid_to_make, max(DAILY_SALARY * 0.3, min(yesterday_bids) + 1))

    final_bid = min(my_status['budget'], bid_to_make)

    # Ensure a minimum bid if budget allows, to stay in contention
    if final_bid < DAILY_SALARY * 0.3 and my_status['budget'] >= DAILY_SALARY * 0.3:
        final_bid = DAILY_SALARY * 0.3

    # Aggressive play if significantly ahead in budget and HP
    if my_status['budget'] > DAILY_SALARY * 5 and my_status['hp'] > 7 and day_context['day'] < EPISODE_DAYS - 1:
        if yesterday_bids:
            final_bid = min(my_status['budget'], max(final_bid, highest_prev_bid + 10))
        else:
            final_bid = min(my_status['budget'], max(final_bid, DAILY_SALARY * 0.8))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return int(min(budget, DAILY_SALARY * 0.4))

    # Get yesterday's max bid among alive opponents
    max_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if prev['bid'] > max_prev_bid:
                max_prev_bid = prev['bid']

    # Urgency: need water if no_water_days > 0 or hp too low
    urgent = (no_water_days > 0) or (hp <= 2)
    # Very urgent: about to die of thirst (no_water_days >= 2) or hp very low
    very_urgent = (no_water_days >= 2) or (hp <= 1)

    if very_urgent:
        # Bid very high to secure water
        target_bid = min(budget, DAILY_SALARY * 1.0)
        return int(target_bid)
    elif urgent:
        # Slightly under the max if possible, but ensure we beat if needed
        target_bid = min(budget, max_prev_bid + 5)
        return int(target_bid)
    else:
        # Not urgent: we can try to save money
        # If supply is high, we can afford to bid low and still maybe win
        # But opponents are aggressive, so bid just above their previous max if we want to win
        # Decide based on day: early days we can afford to lose some, later days must be careful
        if day <= 3:
            # Early: try to win cheaply if possible
            target_bid = min(budget, max_prev_bid + 1)
        else:
            # Late: need to secure water, bid a bit higher
            target_bid = min(budget, max_prev_bid + 3)
        # Ensure bid is not too low if we need water
        # But if we have enough hp, we can risk losing once
        # Cap at a reasonable maximum
        target_bid = max(target_bid, 0.0)
        return int(min(budget, target_bid))
